require_once __DIR__.'/../includes/bootstrap.php';if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);header('Allow: POST');exit('Metode tidak diizinkan.');}verify_csrf();$workspace=require_permission('build_dashboard');$widgetId=filter_var($_POST['widget_id']??null,FILTER_VALIDATE_INT);$dashboardId=filter_var($_POST['dashboard_id']??null,FILTER_VALIDATE_INT);$st=$GLOBALS['pdo']->prepare('SELECT w.id FROM dashboard_widgets w JOIN dashboards d ON d.id=w.dashboard_id WHERE w.id=? AND d.id=? AND d.workspace_id=?');$st->execute([$widgetId,$dashboardId,$workspace['id']]);if(!$st->fetchColumn()){flash('error','Widget tidak ditemukan.');redirect('dashboards/index.php');}$GLOBALS['pdo']->prepare('DELETE FROM dashboard_widgets WHERE id=?')->execute([$widgetId]);audit_log('dashboard.widget_deleted','dashboard',(int)$dashboardId,['widget_id'=>(int)$widgetId]);flash('success','Widget dihapus.');redirect('dashboards/view.php?id='.(int)$dashboardId);
